def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\s*(<=|>=|<>|[A-Z][1-9][0-9]?|SUM|MIN|MAX|IF|"
        r"[0-9]+|[()+*/,:<>=-])"
    )
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "u-": 3,
    }

    def parse(text):
        tokens = token_pattern.findall(text)
        values = []
        operators = []
        expecting_operand = True
        i = 0

        def apply_operator():
            op = operators.pop()
            if op == "u-":
                values.append(("neg", values.pop()))
            else:
                right = values.pop()
                left = values.pop()
                values.append(("binary", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token in ("SUM", "MIN", "MAX", "IF"):
                operators.append(("function", token, 0))
                i += 2  # Skip the function name and its opening parenthesis.
                expecting_operand = True
                continue

            if token == "(":
                operators.append(("paren",))
                expecting_operand = True
            elif token == ",":
                while isinstance(operators[-1], str):
                    apply_operator()
                marker = operators[-1]
                operators[-1] = ("function", marker[1], marker[2] + 1)
                expecting_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    apply_operator()
                marker = operators.pop()
                if marker[0] == "function":
                    count = marker[2] + 1
                    args = values[-count:]
                    del values[-count:]
                    values.append(("function", marker[1], args))
                expecting_operand = False
            elif token in precedence:
                op = "u-" if token == "-" and expecting_operand else token
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "u-"
                        )
                    )
                ):
                    apply_operator()
                operators.append(op)
                expecting_operand = True
            elif token[0].isdigit():
                values.append(("number", int(token)))
                expecting_operand = False
            else:
                if i + 1 < len(tokens) and tokens[i + 1] == ":":
                    values.append(("range", token, tokens[i + 2]))
                    i += 2
                else:
                    values.append(("reference", token))
                expecting_operand = False
            i += 1

        while operators:
            apply_operator()
        return values[0]

    def range_cells(first, last):
        left = min(ord(first[0]), ord(last[0]))
        right = max(ord(first[0]), ord(last[0]))
        top = min(int(first[1:]), int(last[1:]))
        bottom = max(int(first[1:]), int(last[1:]))
        for row in range(top, bottom + 1):
            for column in range(left, right + 1):
                name = chr(column) + str(row)
                if name in cells:
                    yield ("reference", name)

    results = {}
    active = set()

    def evaluate(name):
        tasks = [("cell", name)]
        values = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                cell = task[1]
                if cell not in cells:
                    values.append(0)
                elif cell in results:
                    values.append(results[cell])
                elif cell in active:
                    values.append("#CYCLE!")
                else:
                    active.add(cell)
                    content = cells[cell]
                    tasks.append(("finish_cell", cell))
                    if content.startswith("="):
                        tasks.append(("eval", parse(content[1:])))
                    else:
                        values.append(int(content))

            elif kind == "finish_cell":
                cell = task[1]
                active.remove(cell)
                results[cell] = values[-1]

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    values.append(node[1])
                elif node_kind == "reference":
                    tasks.append(("cell", node[1]))
                elif node_kind == "neg":
                    tasks.append(("neg",))
                    tasks.append(("eval", node[1]))
                elif node_kind == "binary":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                else:
                    function, args = node[1], node[2]
                    if function == "IF":
                        condition = args[0]
                        tasks.append(("if_condition", args[1], args[2]))
                        tasks.append(("eval", condition))
                    else:
                        expanded = []
                        for arg in args:
                            if arg[0] == "range":
                                expanded.extend(range_cells(arg[1], arg[2]))
                            else:
                                expanded.append(arg)
                        tasks.append(("aggregate", function, expanded, 0, None))

            elif kind == "neg":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                right = values.pop()
                op, left = task[1], task[2]
                if isinstance(right, str):
                    values.append(right)
                elif op == "+":
                    values.append(left + right)
                elif op == "-":
                    values.append(left - right)
                elif op == "*":
                    values.append(left * right)
                elif op == "/":
                    if right == 0:
                        values.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        values.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    values.append(left == right)
                elif op == "<>":
                    values.append(left != right)
                elif op == "<":
                    values.append(left < right)
                elif op == "<=":
                    values.append(left <= right)
                elif op == ">":
                    values.append(left > right)
                else:
                    values.append(left >= right)

            elif kind == "if_condition":
                condition = values.pop()
                if isinstance(condition, str):
                    values.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "aggregate":
                function, args, index, accumulator = task[1:]
                if index == len(args):
                    values.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append(("aggregate_value", function, args, index, accumulator))
                    tasks.append(("eval", args[index]))

            else:  # aggregate_value
                function, args, index, accumulator = task[1:]
                value = values.pop()
                if isinstance(value, str):
                    values.append(value)
                else:
                    if accumulator is None:
                        accumulator = value
                    elif function == "SUM":
                        accumulator += value
                    elif function == "MIN":
                        accumulator = min(accumulator, value)
                    else:
                        accumulator = max(accumulator, value)
                    tasks.append(("aggregate", function, args, index + 1, accumulator))

        return values.pop()

    for name in cells:
        if name not in results:
            evaluate(name)

    return {name: results[name] for name in cells}
